17	static void lcd_cfg_panel_info(struct panel_extend_para *info)
18	{
19	    u32 i;
20	    u32 j;
21	    u32 items;
22	    u8 lcd_gamma_tbl[][2] = {
23	        {0, 0}, {15, 15}, {30, 30}, {45, 45}, {60, 60}, {75, 75},
24	        {90, 90}, {105, 105}, {120, 120}, {135, 135}, {150, 150},
25	        {165, 165}, {180, 180}, {195, 195}, {210, 210}, {225, 225},
26	        {240, 240}, {255, 255},
27	    };
28	    u32 lcd_cmap_tbl[2][3][4] = {
29	        {
30	            {LCD_CMAP_G0, LCD_CMAP_B1, LCD_CMAP_G2, LCD_CMAP_B3},
31	            {LCD_CMAP_B0, LCD_CMAP_R1, LCD_CMAP_B2, LCD_CMAP_R3},
32	            {LCD_CMAP_R0, LCD_CMAP_G1, LCD_CMAP_R2, LCD_CMAP_G3},
33	        },
34	        {
35	            {LCD_CMAP_B3, LCD_CMAP_G2, LCD_CMAP_B1, LCD_CMAP_G0},
36	            {LCD_CMAP_R3, LCD_CMAP_B2, LCD_CMAP_R1, LCD_CMAP_B0},
37	            {LCD_CMAP_G3, LCD_CMAP_R2, LCD_CMAP_G1, LCD_CMAP_R0},
38	        },
39	    };
40	
41	    if (!info) {
42	        return;
43	    }
44	
45	    memset(info, 0, sizeof(struct panel_extend_para));
46	    items = sizeof(lcd_gamma_tbl) / 2;
47	    for (i = 0; i < items - 1; i++) {
48	        u32 num = lcd_gamma_tbl[i + 1][0] - lcd_gamma_tbl[i][0];
49	
50	        for (j = 0; j < num; j++) {
51	            u32 value = lcd_gamma_tbl[i][1] +
52	                ((lcd_gamma_tbl[i + 1][1] - lcd_gamma_tbl[i][1]) * j) / num;
53	            info->lcd_gamma_tbl[lcd_gamma_tbl[i][0] + j] =
54	                (value << 16) + (value << 8) + value;
55	        }
56	    }
57	
58	    info->lcd_gamma_tbl[255] = (lcd_gamma_tbl[items - 1][1] << 16) +
59	                               (lcd_gamma_tbl[items - 1][1] << 8) +
60	                               lcd_gamma_tbl[items - 1][1];
61	    memcpy(info->lcd_cmap_tbl, lcd_cmap_tbl, sizeof(lcd_cmap_tbl));
62	}
