83	static int sec_ts_i2c_read(FAR struct sec_ts_touch_dev_s *priv,
84	                           uint8_t reg, FAR uint8_t *buffer, size_t buflen)
85	{
86	  struct i2c_msg_s msg[2];
87	  int ret;
88	
89	  DEBUGASSERT(priv && priv->i2c);
90	
91	  msg[0].frequency = priv->frequency;
92	  msg[0].addr      = SEC_TS_I2C_ADDR;
93	  msg[0].flags     = 0;
94	  msg[0].buffer    = &reg;
95	  msg[0].length    = 1;
96	
97	  msg[1].frequency = priv->frequency;
98	  msg[1].addr      = SEC_TS_I2C_ADDR;
99	  msg[1].flags     = I2C_M_READ;
100	  msg[1].buffer    = buffer;
101	  msg[1].length    = buflen;
102	
103	  ret = I2C_TRANSFER(priv->i2c, msg, 2);
104	  if (ret < 0)
105	    {
106	      ierr("SEC_TS: I2C read reg 0x%02x failed: %d\n", reg, ret);
107	      return ret;
108	    }
109	
110	  return OK;
111	}
112	
113	static int sec_ts_i2c_write(FAR struct sec_ts_touch_dev_s *priv,
114	                            uint8_t reg, FAR const uint8_t *data, size_t len)
115	{
116	  struct i2c_msg_s msg;
117	  uint8_t buf[16];
118	  int ret;
119	
120	  DEBUGASSERT(priv && priv->i2c);
121	
122	  if (len > sizeof(buf) - 1)
123	    {
124	      return -EINVAL;
125	    }
126	
127	  buf[0] = reg;
128	  if (len > 0 && data != NULL)
129	    {
130	      memcpy(&buf[1], data, len);
131	    }
132	
133	  msg.frequency = priv->frequency;
134	  msg.addr      = SEC_TS_I2C_ADDR;
135	  msg.flags     = 0;
136	  msg.buffer    = buf;
137	  msg.length    = 1 + len;
138	
139	  ret = I2C_TRANSFER(priv->i2c, &msg, 1);
140	  if (ret < 0)
141	    {
142	      ierr("SEC_TS: I2C write reg 0x%02x failed: %d\n", reg, ret);
143	      return ret;
144	    }
145	
146	  return OK;
147	}
148	
149	static int sec_ts_wait_for_ready(FAR struct sec_ts_touch_dev_s *priv,
150	                                 uint8_t ack)
151	{
152	  uint8_t event[SEC_TS_EVENT_BUFF_SIZE];
153	  int retry;
154	
155	  for (retry = 0; retry <= SEC_TS_WAIT_RETRY_CNT; retry++)
156	    {
157	      if (sec_ts_i2c_read(priv, SEC_TS_READ_ONE_EVENT, event,
158	                          SEC_TS_EVENT_BUFF_SIZE) < 0)
159	        {
160	          return -EIO;
161	        }
162	
163	      if (event[0] == TYPE_STATUS_EVENT_ACK && event[1] == ack)
164	        {
165	          return OK;
166	        }
167	
168	      sec_ts_delay_ms(20);
169	    }
170	
171	  ierr("SEC_TS: wait_for_ready 0x%02x timeout\n", ack);
172	  return -ETIMEDOUT;
173	}
