175	static int sec_ts_read_device_id(FAR struct sec_ts_touch_dev_s *priv)
176	{
177	  uint8_t device_id[3];
178	  int ret;
179	
180	  ret = sec_ts_i2c_read(priv, SEC_TS_READ_DEVICE_ID, device_id,
181	                        sizeof(device_id));
182	  if (ret < 0)
183	    {
184	      return ret;
185	    }
186	
187	  iinfo("SEC_TS: device id %02x %02x %02x\n",
188	        device_id[0], device_id[1], device_id[2]);
189	
190	  if (device_id[0] != SEC_TS_ID_ON_FW)
191	    {
192	      ierr("SEC_TS: firmware not ready (id[0]=0x%02x)\n", device_id[0]);
193	      return -ENODEV;
194	    }
195	
196	  return OK;
197	}
