199	static int sec_ts_hw_init(FAR struct sec_ts_touch_dev_s *priv)
200	{
201	  int ret;
202	
203	  hal_gpio_pinmux_set_function(TP_LDO_EN, GPIO_MUXSEL_OUT);
204	  hal_gpio_set_driving_level(TP_LDO_EN, GPIO_DRIVING_LEVEL3);
205	  hal_gpio_set_direction(TP_LDO_EN, GPIO_DIRECTION_OUTPUT);
206	  hal_gpio_set_data(TP_LDO_EN, GPIO_DATA_HIGH);
207	  sec_ts_delay_ms(10);
208	
209	  hal_gpio_pinmux_set_function(TP_INT, GPIO_MUXSEL_IN);
210	  hal_gpio_set_direction(TP_INT, GPIO_DIRECTION_INPUT);
211	  hal_gpio_set_pull(TP_INT, GPIO_PULL_UP);
212	
213	  /* Touch shares LCD reset (PD19); wait for panel power-up sequence. */
214	  sec_ts_delay_ms(200);
215	
216	  ret = sec_ts_read_device_id(priv);
217	  if (ret < 0)
218	    {
219	      ret = sec_ts_i2c_write(priv, SEC_TS_CMD_SW_RESET, NULL, 0);
220	      if (ret < 0)
221	        {
222	          return ret;
223	        }
224	
225	      sec_ts_delay_ms(500);
226	      ret = sec_ts_wait_for_ready(priv, SEC_TS_ACK_BOOT_COMPLETE);
227	      if (ret < 0)
228	        {
229	          return ret;
230	        }
231	
232	      ret = sec_ts_read_device_id(priv);
233	      if (ret < 0)
234	        {
235	          return ret;
236	        }
237	    }
238	
239	  priv->touch_functions = SEC_TS_BIT_SETFUNC_MUTUAL;
240	  ret = sec_ts_i2c_write(priv, SEC_TS_CMD_SET_TOUCHFUNCTION,
241	                         &priv->touch_functions, 1);
242	  if (ret < 0)
243	    {
244	      return ret;
245	    }
246	
247	  ret = sec_ts_i2c_write(priv, SEC_TS_CMD_SENSE_ON, NULL, 0);
248	  if (ret < 0)
249	    {
250	      return ret;
251	    }
252	
253	  sec_ts_delay_ms(50);
254	  return OK;
255	}
