257	static void sec_ts_report_point(FAR struct sec_ts_touch_dev_s *priv,
258	                                FAR struct touch_sample_s *sample,
259	                                int slot, uint16_t x, uint16_t y,
260	                                uint8_t pressure, uint8_t flags)
261	{
262	  if (slot < 0 || slot >= SEC_TS_MAX_TOUCH_POINTS)
263	    {
264	      return;
265	    }
266	
267	  sample->npoints = 1;
268	  sample->point[0].id = slot;
269	  sample->point[0].x = x;
270	  sample->point[0].y = y;
271	  sample->point[0].w = 0;
272	  sample->point[0].h = 0;
273	  sample->point[0].pressure = pressure;
274	  sample->point[0].flags = flags & TOUCH_EVENT_MASK;
275	  sample->point[0].timestamp = touch_get_time();
276	
277	  touch_event(priv->lower.priv, sample);
278	}
