280	static void sec_ts_read_events(FAR struct sec_ts_touch_dev_s *priv)
281	{
282	  struct touch_sample_s sample;
283	  uint8_t event[SEC_TS_EVENT_BUFF_SIZE];
284	  int loop;
285	  int remain;
286	
287	  remain = 1;
288	  for (loop = 0; loop < SEC_TS_MAX_EVENT_LOOP && remain; loop++)
289	    {
290	      FAR struct sec_ts_event_coordinate_s *coord;
291	      int t_id;
292	      uint16_t x;
293	      uint16_t y;
294	      int ret;
295	
296	      ret = sec_ts_i2c_read(priv, SEC_TS_READ_ONE_EVENT, event,
297	                            SEC_TS_EVENT_BUFF_SIZE);
298	      if (ret < 0)
299	        {
300	          return;
301	        }
302	
303	      if ((event[0] >> 6) == SEC_TS_Status_Event)
304	        {
305	          remain = 0;
306	          continue;
307	        }
308	
309	      if ((event[0] >> 6) != SEC_TS_Coordinate_Event)
310	        {
311	          remain = 0;
312	          continue;
313	        }
314	
315	      coord = (FAR struct sec_ts_event_coordinate_s *)event;
316	      t_id = (int)coord->tid - 1;
317	      if (t_id < 0 || t_id >= SEC_TS_MAX_TOUCH_POINTS)
318	        {
319	          remain = 1;
320	          continue;
321	        }
322	
323	      if (coord->ttype != SEC_TS_TOUCHTYPE_NORMAL)
324	        {
325	          remain = 1;
326	          continue;
327	        }
328	
329	      x = ((uint16_t)coord->x_11_4 << 4) | coord->x_3_0;
330	      y = ((uint16_t)coord->y_11_4 << 4) | coord->y_3_0;
331	
332	      if (x > SEC_TS_LCD_WIDTH)
333	        {
334	          x = SEC_TS_LCD_WIDTH;
335	        }
336	
337	      if (y > SEC_TS_LCD_HEIGHT)
338	        {
339	          y = SEC_TS_LCD_HEIGHT;
340	        }
341	
342	      switch (coord->tchsta)
343	        {
344	        case SEC_TS_Coordinate_Action_Press:
345	          priv->slot_active[t_id] = true;
346	          sec_ts_report_point(priv, &sample, t_id, x, y, coord->z,
347	                              TOUCH_DOWN | TOUCH_ID_VALID);
348	          break;
349	
350	        case SEC_TS_Coordinate_Action_Move:
351	          if (priv->slot_active[t_id])
352	            {
353	              sec_ts_report_point(priv, &sample, t_id, x, y, coord->z,
354	                                  TOUCH_MOVE | TOUCH_ID_VALID);
355	            }
356	          break;
357	
358	        case SEC_TS_Coordinate_Action_Release:
359	          if (priv->slot_active[t_id])
360	            {
361	              sec_ts_report_point(priv, &sample, t_id, x, y, 0,
362	                                  TOUCH_UP | TOUCH_ID_VALID);
363	              priv->slot_active[t_id] = false;
364	            }
365	          break;
366	
367	        default:
368	          break;
369	        }
370	
371	      remain = 1;
372	    }
373	}
