375	static void sec_ts_worker(FAR void *arg)
376	{
377	  FAR struct sec_ts_touch_dev_s *priv = (FAR struct sec_ts_touch_dev_s *)arg;
378	
379	  DEBUGASSERT(priv != NULL);
380	  sec_ts_read_events(priv);
