383	static hal_irqreturn_t sec_ts_interrupt_handler(FAR void *arg)
384	{
385	  FAR struct sec_ts_touch_dev_s *priv = (FAR struct sec_ts_touch_dev_s *)arg;
386	  int ret;
387	
388	  DEBUGASSERT(priv != NULL);
389	
390	  if (priv->work.worker != NULL)
391	    {
392	      return HAL_IRQ_OK;
393	    }
394	
395	  ret = work_queue(HPWORK, &priv->work, sec_ts_worker, priv, 0);
396	  if (ret != 0)
397	    {
398	      ierr("SEC_TS: failed to queue work: %d\n", ret);
399	      return HAL_IRQ_ERR;
400	    }
401	
402	  return HAL_IRQ_OK;
403	}
