405	int sec_ts_register(FAR const char *devpath, FAR struct i2c_master_s *dev)
406	{
407	  FAR struct sec_ts_touch_dev_s *priv = &g_sec_ts_touch;
408	  int ret;
409	  int i;
410	
411	  if (dev == NULL)
412	    {
413	      return -EINVAL;
414	    }
415	
416	  priv->i2c = dev;
417	  for (i = 0; i < SEC_TS_MAX_TOUCH_POINTS; i++)
418	    {
419	      priv->slot_active[i] = false;
420	    }
421	
422	  ret = sec_ts_hw_init(priv);
423	  if (ret < 0)
424	    {
425	      ierr("SEC_TS: hardware init failed: %d\n", ret);
426	      return ret;
427	    }
428	
429	  hal_gpio_to_irq(TP_INT, &priv->irq);
430	  hal_gpio_irq_request(priv->irq, sec_ts_interrupt_handler,
431	                       IRQ_TYPE_EDGE_FALLING, priv);
432	
433	  ret = touch_register(&priv->lower, devpath, SEC_TS_MAX_TOUCH_POINTS);
434	  if (ret < 0)
435	    {
436	      ierr("SEC_TS: touch_register failed: %d\n", ret);
437	      hal_gpio_irq_free(priv->irq);
438	      return ret;
439	    }
440	
441	  hal_gpio_irq_enable(priv->irq);
442	  iinfo("SEC_TS: registered on %s\n", devpath);
443	  return OK;
444	}
445	
446	void sec_ts_unregister(FAR const char *devpath)
447	{
448	  FAR struct sec_ts_touch_dev_s *priv = &g_sec_ts_touch;
449	
450	  hal_gpio_irq_disable(priv->irq);
451	  hal_gpio_irq_free(priv->irq);
