text:
这是一个非常典型且硬核的嵌入式显示驱动移植问题。你能把 1080×2160 这种高分辨率的手机竖屏在 R528 (T113-S3) 这种原本主打 1080P/720P 的低功耗芯片上点亮，并且画面稳定、背光正常，说明硬件引脚、DPHY 物理层、时钟树分频以及 MIPI 初始化序列（0x11/0x29）已经 90% 正确了。出现 “LOGO 残缺、上半部分画面跑到了屏幕下半部分（垂直回绕/偏移）” 的现象，且调整普通的 hbp/vbp/hfp/vfp 均无济于事，直击了一个隐藏极深的底层硬件限制：全志 DE2.0 / TCON0 的 11 位（2048 像素）寄存器边界溢出。核心原因深度剖析：11位寄存器溢出（2048限制）全志 R528/T113 的显示子系统（DE2.0 + TCON0）在底层设计时，其目标最大分辨率通常是 1920×1080 @ 60fps。为了节省硬件闸门成本，芯片内部许多关于垂直方向（Vertical）的计数器和延迟寄存器，其位宽被硬限制在了 11 位（Maximum = 2047）。我们在你的 6fhd_debug_report.md 中看到了这一行关键的底层驱动行为：video_start_delay = lcd_y + lcd_vbp + 1 = 2160 + 12 + 1 = 2173(lcd_vt = 2182, 所以 delay 在 vfp 区域: 2182-2173=9行 before next vsync)致命的数学溢出：在全志的 de_dsi.c 底层中，这个 video_start_delay（或者是 TCON 内部对应的起始延迟寄存器）如果只有 11 位宽：预期的寄存器值：$2173$（二进制：1000 0110 1101）11位硬件截断（& 0x7FF）后实际值：$125$（二进制：000 0110 1101）导致的结果：本来 Display Engine (DE) 应该在当前帧结束前最后 9 行（第 2173 行）才开始往 TCON FIFO 丢下一帧的数据。但因为溢出变成了 125，DE 在前一帧刚开始没多久（第 125 行）就误以为要开始传输了。这导致 TCON 的读指针和 DE 的写指针发生了严重的同步错位，下一帧头部的 112 行数据被强行挤进了当前帧的尾部显示（即屏幕最下方），而本帧剩余的数据整体向上发生滚动截断。这就是你看到的“上半部分跑到了最下面”的完美解释。攻坚解决方案与驱动配置修改要解决这种硬件级别的边界溢出，我们有两个方向：方案 A（降级规避验证法） 和 方案 B（时序欺骗法）。方案 A：1920 垂直行极限测试（强烈建议优先烧录验证）我们将 active 的垂直分辨率人为降低到 1920（小于2048），将其余的 240 行全部填入 Vertical Porch（消隐区）中。这样既能保证总行数 lcd_vt 依然等于面板固定的 2182（维持面板锁相环稳定），又能让 video_start_delay 降到 2048 以下，彻底避开溢出。请将你的板级配置文件（soc/mipi_6fhd_config.c 或对应 sys_config.fex 映射区）修改为以下参数：Ini, TOMLlcd_driver_name = "mipi_6fhd"
lcd_if = 4                  ; DSI
lcd_x = 1080
lcd_y = 1920                ; 【修改】从 2160 降到 1920，规避 2048 硬件限制
lcd_dclk_freq = 52          ; 保持 52MHz 

lcd_dsi_if = 0              ; Video mode
lcd_dsi_lane = 4
lcd_dsi_format = 0           ; RGB888

; --- 水平时序保持不变 ---
lcd_ht = 1180
lcd_hbp = 40
lcd_hfp = 60
lcd_hspw = 10

; --- 垂直时序重构（总行数 lcd_vt 必须保持 2182） ---
lcd_vt = 2182               ; 保持 2182，确保面板刷新率不丢失同步
lcd_vbp = 12                ; 保持 12
lcd_vspw = 2                ; 保持 2
lcd_vfp = 250               ; 【修改】2182 - 1920 - 12 = 250 (将缺失的240行当作前肩抛掉)

; --- Framebuffer 同时修改 ---
fb0_width = 1080
fb0_height = 1920           ; 【修改】同步调整
fb0_buffer_num = 2
预期表现：若此假说成立，烧录此固件后，画面包裹错位现象将彻底消失。LOGO 能够完整居中或靠顶正常显示，只有屏幕最下方会有 240 行的物理黑带（或不确定像素）。方案 B：如果必须跑满 2160 全分辨率（修改底层驱动）如果你测试方案 A 成功后，确认是溢出问题，但产品要求必须用满 2160 物理全高，你需要修改未触碰过的底层驱动 disp/de/lowlevel_v2x/de_dsi.c（或 de_dsi_v40.c）。请全局搜索 video_start_delay 的赋值语句，通常长这样：Cu32 video_start_delay = panel_info->lcd_y + panel_info->lcd_vbp + 1;
将其强行修改为一个较小的固定值（例如固定为 32 或 64），绕过全志默认的超大延迟计算公式：C// 强行硬编码一个在 11 位内绝不溢出的行数
u32 video_start_delay = panel_info->lcd_vbp + 4; 
或者，检查该寄存器写入时是否有类似 & 0x7FF 的显式误写掩码，若有，确认硬件手册后尝试将其放宽至 & 0xFFF（12位）。优化后的 Panel 核心驱动源码 (mipi_6fhd.c)结合全志 DSI 核心在 NuttX / OpenVela 下的特性，对你提供的 mipi_6fhd.c 进行了结构精简与规整。移除了冗余的 Gamma 和 Cmap 映射（避免非标 RGB 转换带来的潜在 Stride 混乱），重点保证上电序列与复位脉冲宽度。C/****************************************************************************
 * vendor/allwinnertech/chips/r528/drivers/rtos-hal/hal/source/disp2/disp/lcd/mipi_6fhd.c
 *
 * 6FHD MIPI DSI panel driver (1080x2160/1080x1920).
 ****************************************************************************/

#include "mipi_6fhd.h"

static void lcd_power_on(u32 sel);
static void lcd_power_off(u32 sel);
static void lcd_bl_open(u32 sel);
static void lcd_bl_close(u32 sel);
static void lcd_panel_init(u32 sel);
static void lcd_panel_exit(u32 sel);

#define panel_reset(sel, val) sunxi_lcd_gpio_set_value(sel, 0, val)

static void lcd_cfg_panel_info(struct panel_extend_para *info)
{
    /* 关掉复杂的 Cmap 和 Gamma，防止 DE 引入不必要的颜色和步长 Stride 转换问题 */
    memset(info, 0, sizeof(struct panel_extend_para));
}

static s32 lcd_open_flow(u32 sel)
{
    LCD_OPEN_FUNC(sel, lcd_power_on, 20);
    LCD_OPEN_FUNC(sel, lcd_panel_init, 50);
    LCD_OPEN_FUNC(sel, sunxi_lcd_tcon_enable, 30);
    LCD_OPEN_FUNC(sel, lcd_bl_open, 0);
    return 0;
}

static s32 lcd_close_flow(u32 sel)
{
    LCD_CLOSE_FUNC(sel, lcd_bl_close, 0);
    LCD_CLOSE_FUNC(sel, sunxi_lcd_tcon_disable, 0);
    LCD_CLOSE_FUNC(sel, lcd_panel_exit, 100);
    LCD_CLOSE_FUNC(sel, lcd_power_off, 200);
    return 0;
}

static void lcd_power_on(u32 sel)
{
    /* 精准对齐 RK3566 DTSI 声明的 120ms reset-delay 与时序要求 */
    sunxi_lcd_power_enable(sel, 0);      /* IOVDD 1.8V (DCDC1) */
    sunxi_lcd_delay_ms(15);
    sunxi_lcd_power_enable(sel, 1);      /* 核心 1.8V (DCDC3) */
    sunxi_lcd_delay_ms(15);

    sunxi_lcd_pin_cfg(sel, 1);           /* 配置 MIPI 引脚 */
    sunxi_lcd_delay_ms(20);

    /* 产生标准的硬件复位负脉冲 */
    panel_reset(sel, 1);                 
    sunxi_lcd_delay_ms(20);
    panel_reset(sel, 0);                 /* 拉低复位 */
    sunxi_lcd_delay_ms(50);              /* 维持负脉冲 */
    panel_reset(sel, 1);                 /* 重新拉高 */
    sunxi_lcd_delay_ms(120);             /* 对齐 dtsi 中的 reset-delay-ms = <120> */

    sunxi_lcd_power_enable(sel, 2);      /* AVDD 3.3V (DCDC2) */
    sunxi_lcd_delay_ms(20);
}

static void lcd_power_off(u32 sel)
{
    sunxi_lcd_pin_cfg(sel, 0);
    sunxi_lcd_delay_ms(10);
    panel_reset(sel, 0);
    sunxi_lcd_delay_ms(10);
    sunxi_lcd_power_disable(sel, 2);
    sunxi_lcd_power_disable(sel, 1);
    sunxi_lcd_power_disable(sel, 0);
}

static void lcd_bl_open(u32 sel)
{
    sunxi_lcd_pwm_enable(sel);
    sunxi_lcd_backlight_enable(sel);
}

static void lcd_bl_close(u32 sel)
{
    sunxi_lcd_backlight_disable(sel);
    sunxi_lcd_pwm_disable(sel);
}

static void lcd_panel_init(u32 sel)
{
    /* 在发送 DCS 指令前拉开 LP 状态下的 DSI 时钟 */
    sunxi_lcd_dsi_clk_enable(sel);
    sunxi_lcd_delay_ms(20);

    /* 发送 0x11 Sleep Out */
    sunxi_lcd_dsi_dcs_write_0para(sel, DSI_DCS_EXIT_SLEEP_MODE);
    sunxi_lcd_delay_ms(120);             /* 退出休眠必须严格等待 120ms */

    /* 发送 0x29 Display On */
    sunxi_lcd_dsi_dcs_write_0para(sel, DSI_DCS_SET_DISPLAY_ON);
    sunxi_lcd_delay_ms(20);
}

static void lcd_panel_exit(u32 sel)
{
    sunxi_lcd_dsi_dcs_write_0para(sel, DSI_DCS_SET_DISPLAY_OFF);
    sunxi_lcd_delay_ms(20);
    sunxi_lcd_dsi_dcs_write_0para(sel, DSI_DCS_ENTER_SLEEP_MODE);
    sunxi_lcd_delay_ms(80);
}

static s32 lcd_user_defined_func(u32 sel, u32 para1, u32 para2, u32 para3)
{
    return 0;
}

struct __lcd_panel mipi_6fhd_panel = {
    .name = "mipi_6fhd",
    .func = {
        .cfg_panel_info = lcd_cfg_panel_info,
        .cfg_open_flow = lcd_open_flow,
        .cfg_close_flow = lcd_close_flow,
        .lcd_user_defined_func = lcd_user_defined_func,
    },
};
下一步行动建议先不要动底层复杂的 de_dsi.c。请直接修改你板级配置中的时序参数为 1080×1920 方案 A，编译并烧录。如果回绕现象立刻消失，就能稳稳斩断所有迷茫，证明百分之百是底层硬件寄存器在 $>2048$ 时发生截断溢出。祝你顺利收尾这个高难度的屏幕迁移任务！跟高级AI要到饭了。按它的计划进行测试吧

